1	package com.airbnb.lottie;
2	
3	import android.os.Handler;
4	import android.os.Looper;
5	
6	import androidx.annotation.Nullable;
7	import androidx.annotation.RestrictTo;
8	
9	import com.airbnb.lottie.utils.Logger;
10	import com.airbnb.lottie.utils.LottieThreadFactory;
11	
12	import java.util.ArrayList;
13	import java.util.LinkedHashSet;
14	import java.util.List;
15	import java.util.Set;
16	import java.util.concurrent.Callable;
17	import java.util.concurrent.ExecutionException;
18	import java.util.concurrent.Executor;
19	import java.util.concurrent.Executors;
20	import java.util.concurrent.FutureTask;
21	
22	/**
23	 * Helper to run asynchronous tasks with a result.
24	 * Results can be obtained with {@link #addListener(LottieListener)}.
25	 * Failures can be obtained with {@link #addFailureListener(LottieListener)}.
26	 * <p>
27	 * A task will produce a single result or a single failure.
28	 */
29	@SuppressWarnings("UnusedReturnValue")
30	public class LottieTask<T> {
31	  static final String DIRECT_EXECUTOR_PROPERTY_NAME = "lottie.testing.directExecutor";
32	
33	  /**
34	   * The executor which runs {@code LottieTask}s such as composition parsing and url fetching.
35	   * <p>
36	   * You may change this to run synchronously for testing. Additionally, if the
37	   * {@code lottie.testing.directExecutor} system property is set to "true", the initial value
38	   * will be a synchronous executor suitable for use in tests.
39	   */
40	  @SuppressWarnings("WeakerAccess")
41	  public static Executor EXECUTOR;
42	  static {
43	    if ("true".equals(System.getProperty(DIRECT_EXECUTOR_PROPERTY_NAME))) {
44	      EXECUTOR = Runnable::run;
45	    } else {
46	      EXECUTOR = Executors.newCachedThreadPool(new LottieThreadFactory());
47	    }
48	  }
49	
50	  /* Preserve add order. */
51	  private final Set<LottieListener<T>> successListeners = new LinkedHashSet<>(1);
52	  private final Set<LottieListener<Throwable>> failureListeners = new LinkedHashSet<>(1);
53	
54	  /**
55	   * Handler to notify listener on UI thread. If view is rendered on per-window UI thread, app should override
56	   * {@link Context#getMainLooper()} for the {@link WindowContext} that hosts the view tree so that uiHandler
57	   * will point to the per-window ui thread.
58	   */
59	  private final Handler uiHandler;
60	
61	  @Nullable private volatile LottieResult<T> result = null;
62	
63	  @RestrictTo(RestrictTo.Scope.LIBRARY)
64	  public LottieTask(Looper uiLooper, Callable<LottieResult<T>> runnable) {
65	    this(uiLooper, runnable, false);
66	  }
67	
68	  public LottieTask(T result) {
69	    this(Looper.getMainLooper(), result);
70	  }
71	
72	  public LottieTask(Looper uiLooper, T result) {
73	    uiHandler = new Handler(uiLooper);
74	    setResult(new LottieResult<>(result));
75	  }
76	
77	  /**
78	   * runNow is only used for testing.
79	   */
80	  @RestrictTo(RestrictTo.Scope.LIBRARY) LottieTask(Looper uiLooper, Callable<LottieResult<T>> runnable, boolean runNow) {
81	    uiHandler = new Handler(uiLooper);
82	    if (runNow) {
83	      try {
84	        setResult(runnable.call());
85	      } catch (Throwable e) {
86	        setResult(new LottieResult<>(e));
87	      }
88	    } else {
89	      EXECUTOR.execute(new LottieFutureTask<T>(this, runnable));
90	    }
91	  }
92	
93	  private void setResult(@Nullable LottieResult<T> result) {
94	    if (this.result != null) {
95	      throw new IllegalStateException("A task may only be set once.");
96	    }
97	    this.result = result;
98	    notifyListeners();
99	  }
100	
101	  /**
102	   * Add a task listener. If the task has completed, the listener will be called synchronously.
103	   *
104	   * @return the task for call chaining.
105	   */
106	  public synchronized LottieTask<T> addListener(LottieListener<T> listener) {
107	    LottieResult<T> result = this.result;
108	    if (result != null && result.getValue() != null) {
109	      listener.onResult(result.getValue());
110	    }
111	
112	    successListeners.add(listener);
113	    return this;
114	  }
115	
116	  /**
117	   * Remove a given task listener. The task will continue to execute so you can re-add
118	   * a listener if necessary.
119	   *
120	   * @return the task for call chaining.
121	   */
122	  public synchronized LottieTask<T> removeListener(LottieListener<T> listener) {
123	    successListeners.remove(listener);
124	    return this;
125	  }
126	
127	  /**
128	   * Add a task failure listener. This will only be called in the even that an exception
129	   * occurs. If an exception has already occurred, the listener will be called immediately.
130	   *
131	   * @return the task for call chaining.
132	   */
133	  public synchronized LottieTask<T> addFailureListener(LottieListener<Throwable> listener) {
134	    LottieResult<T> result = this.result;
135	    if (result != null && result.getException() != null) {
136	      listener.onResult(result.getException());
137	    }
138	
139	    failureListeners.add(listener);
140	    return this;
141	  }
142	
143	  /**
144	   * Remove a given task failure listener. The task will continue to execute so you can re-add
145	   * a listener if necessary.
146	   *
147	   * @return the task for call chaining.
148	   */
149	  public synchronized LottieTask<T> removeFailureListener(LottieListener<Throwable> listener) {
150	    failureListeners.remove(listener);
151	    return this;
152	  }
153	
154	  @Nullable
155	  public LottieResult<T> getResult() {
156	    return result;
157	  }
158	
159	  private void notifyListeners() {
160	    // Listeners should be called on the ui thread.
161	    if (Looper.myLooper() == uiHandler.getLooper()) {
162	      notifyListenersInternal();
163	    } else {
164	      uiHandler.post(this::notifyListenersInternal);
165	    }
166	  }
167	
168	  private void notifyListenersInternal() {
169	    // Local reference in case it gets set on a background thread.
170	    LottieResult<T> result = LottieTask.this.result;
171	    if (result == null) {
172	      return;
173	    }
174	    if (result.getValue() != null) {
175	      notifySuccessListeners(result.getValue());
176	    } else {
177	      notifyFailureListeners(result.getException());
178	    }
179	  }
180	
181	  private synchronized void notifySuccessListeners(T value) {
182	    // Allows listeners to remove themselves in onResult.
183	    // Otherwise we risk ConcurrentModificationException.
184	    List<LottieListener<T>> listenersCopy = new ArrayList<>(successListeners);
185	    for (LottieListener<T> l : listenersCopy) {
186	      l.onResult(value);
187	    }
188	  }
189	
190	  private synchronized void notifyFailureListeners(Throwable e) {
191	    // Allows listeners to remove themselves in onResult.
192	    // Otherwise we risk ConcurrentModificationException.
193	    List<LottieListener<Throwable>> listenersCopy = new ArrayList<>(failureListeners);
194	    if (listenersCopy.isEmpty()) {
195	      Logger.warning("Lottie encountered an error but no failure listener was added:", e);
196	      return;
197	    }
198	
199	    for (LottieListener<Throwable> l : listenersCopy) {
200	      l.onResult(e);
201	    }
202	  }
203	
204	  private static class LottieFutureTask<T> extends FutureTask<LottieResult<T>> {
205	
206	    private LottieTask<T> lottieTask;
207	
208	    LottieFutureTask(LottieTask<T> task, Callable<LottieResult<T>> callable) {
209	      super(callable);
210	      lottieTask = task;
211	    }
212	
213	    @Override
214	    protected void done() {
215	      try {
216	        if (isCancelled()) {
217	          // We don't need to notify any listeners if the task is cancelled.
218	          return;
219	        }
220	
221	        try {
222	          lottieTask.setResult(get());
223	        } catch (InterruptedException | ExecutionException e) {
224	          lottieTask.setResult(new LottieResult<>(e));
225	        }
226	      } finally {
227	        // LottieFutureTask can be held in memory for up to 60 seconds after the task is done, which would
228	        // result in holding on to the associated LottieTask instance and leaking its listeners. To avoid
229	        // that, we clear our the reference to the LottieTask instance.
230	        //
231	        // How is LottieFutureTask held for up to 60 seconds? It's a bug in how the VM cleans up stack
232	        // local variables. When you have a loop that polls a blocking queue and assigns the result
233	        // to a local variable, after looping the local variable will still reference the previous value
234	        // until the queue returns the next result.
235	        //
236	        // Executors.newCachedThreadPool() relies on a SynchronousQueue and creates a cached thread pool
237	        // with a default keep alice of 60 seconds. After a given worker thread runs a task, that thread
238	        // will wait for up to 60 seconds for a new task to come, and while waiting it's also accidentally
239	        // keeping a reference to the previous task.
240	        //
241	        // See commit d577e728e9bccbafc707af3060ea914caa73c14f in AOSP for how that was fixed for Looper.
242	        lottieTask = null;
243	      }
244	    }
245	  }
246	}
