1	package com.airbnb.lottie.utils;
2	
3	import android.animation.ValueAnimator;
4	import android.view.Choreographer;
5	
6	import androidx.annotation.FloatRange;
7	import androidx.annotation.MainThread;
8	import androidx.annotation.Nullable;
9	import androidx.annotation.VisibleForTesting;
10	
11	import com.airbnb.lottie.L;
12	import com.airbnb.lottie.LottieComposition;
13	
14	/**
15	 * This is a slightly modified {@link ValueAnimator} that allows us to update start and end values
16	 * easily optimizing for the fact that we know that it's a value animator with 2 floats.
17	 */
18	public class LottieValueAnimator extends BaseLottieAnimator implements Choreographer.FrameCallback {
19	
20	
21	  private float speed = 1f;
22	  private boolean speedReversedForRepeatMode = false;
23	  private long lastFrameTimeNs = 0;
24	  private float frameRaw = 0;
25	  private float frame = 0;
26	  private int repeatCount = 0;
27	  private float minFrame = Integer.MIN_VALUE;
28	  private float maxFrame = Integer.MAX_VALUE;
29	  @Nullable private LottieComposition composition;
30	  @VisibleForTesting protected boolean running = false;
31	  private boolean useCompositionFrameRate = false;
32	
33	  public LottieValueAnimator() {
34	  }
35	
36	  /**
37	   * Returns a float representing the current value of the animation from 0 to 1
38	   * regardless of the animation speed, direction, or min and max frames.
39	   */
40	  @Override public Object getAnimatedValue() {
41	    return getAnimatedValueAbsolute();
42	  }
43	
44	  /**
45	   * Returns the current value of the animation from 0 to 1 regardless
46	   * of the animation speed, direction, or min and max frames.
47	   */
48	  @FloatRange(from = 0f, to = 1f) public float getAnimatedValueAbsolute() {
49	    if (composition == null) {
50	      return 0;
51	    }
52	    return (frame - composition.getStartFrame()) / (composition.getEndFrame() - composition.getStartFrame());
53	
54	  }
55	
56	  /**
57	   * Returns the current value of the currently playing animation taking into
58	   * account direction, min and max frames.
59	   */
60	  @Override @FloatRange(from = 0f, to = 1f) public float getAnimatedFraction() {
61	    if (composition == null) {
62	      return 0;
63	    }
64	    if (isReversed()) {
65	      return (getMaxFrame() - frame) / (getMaxFrame() - getMinFrame());
66	    } else {
67	      return (frame - getMinFrame()) / (getMaxFrame() - getMinFrame());
68	    }
69	  }
70	
71	  @Override public long getDuration() {
72	    return composition == null ? 0 : (long) composition.getDuration();
73	  }
74	
75	  public float getFrame() {
76	    return frame;
77	  }
78	
79	  @Override public boolean isRunning() {
80	    return running;
81	  }
82	
83	  public void setUseCompositionFrameRate(boolean useCompositionFrameRate) {
84	    this.useCompositionFrameRate = useCompositionFrameRate;
85	  }
86	
87	  @Override public void doFrame(long frameTimeNanos) {
88	    postFrameCallback();
89	    if (composition == null || !isRunning()) {
90	      return;
91	    }
92	
93	    if (L.isTraceEnabled()) {
94	      L.beginSection("LottieValueAnimator#doFrame");
95	    }
96	    long timeSinceFrame = lastFrameTimeNs == 0 ? 0 : frameTimeNanos - lastFrameTimeNs;
97	    float frameDuration = getFrameDurationNs();
98	    float dFrames = timeSinceFrame / frameDuration;
99	
100	    float newFrameRaw = frameRaw + (isReversed() ? -dFrames : dFrames);
101	    boolean ended = !MiscUtils.contains(newFrameRaw, getMinFrame(), getMaxFrame());
102	    float previousFrameRaw = frameRaw;
103	    frameRaw = MiscUtils.clamp(newFrameRaw, getMinFrame(), getMaxFrame());
104	    frame = useCompositionFrameRate ? (float) Math.floor(frameRaw) : frameRaw;
105	
106	    lastFrameTimeNs = frameTimeNanos;
107	
108	    if (ended) {
109	      if (getRepeatCount() != INFINITE && repeatCount >= getRepeatCount()) {
110	        frameRaw = speed < 0 ? getMinFrame() : getMaxFrame();
111	        frame = frameRaw;
112	        removeFrameCallback();
113	        checkNotifyUpdate(previousFrameRaw);
114	        notifyEnd(isReversed());
115	      } else {
116	        if (getRepeatMode() == REVERSE) {
117	          speedReversedForRepeatMode = !speedReversedForRepeatMode;
118	          reverseAnimationSpeed();
119	        } else {
120	          frameRaw = isReversed() ? getMaxFrame() : getMinFrame();
121	          frame = frameRaw;
122	        }
123	        lastFrameTimeNs = frameTimeNanos;
124	        checkNotifyUpdate(previousFrameRaw);
125	        notifyRepeat();
126	        repeatCount++;
127	      }
128	    } else {
129	      checkNotifyUpdate(previousFrameRaw);
130	    }
131	
132	    verifyFrame();
133	    if (L.isTraceEnabled()) {
134	      L.endSection("LottieValueAnimator#doFrame");
135	    }
136	  }
137	
138	  private void checkNotifyUpdate(float previousFrameRaw) {
139	    if (!useCompositionFrameRate || frameRaw != previousFrameRaw) {
140	      notifyUpdate();
141	    }
142	  }
143	
144	  private float getFrameDurationNs() {
145	    if (composition == null) {
146	      return Float.MAX_VALUE;
147	    }
148	    return Utils.SECOND_IN_NANOS / composition.getFrameRate() / Math.abs(speed);
149	  }
150	
151	  public void clearComposition() {
152	    this.composition = null;
153	    minFrame = Integer.MIN_VALUE;
154	    maxFrame = Integer.MAX_VALUE;
155	  }
156	
157	  public void setComposition(LottieComposition composition) {
158	    // Because the initial composition is loaded async, the first min/max frame may be set
159	    boolean keepMinAndMaxFrames = this.composition == null;
160	    this.composition = composition;
161	
162	    if (keepMinAndMaxFrames) {
163	      setMinAndMaxFrames(
164	          Math.max(this.minFrame, composition.getStartFrame()),
165	          Math.min(this.maxFrame, composition.getEndFrame())
166	      );
167	    } else {
168	      setMinAndMaxFrames((int) composition.getStartFrame(), (int) composition.getEndFrame());
169	    }
170	    float frame = this.frame;
171	    this.frame = 0f;
172	    this.frameRaw = 0f;
173	    setFrame((int) frame);
174	    notifyUpdate();
175	  }
176	
177	  public void setFrame(float frame) {
178	    if (this.frameRaw == frame) {
179	      return;
180	    }
181	    this.frameRaw = MiscUtils.clamp(frame, getMinFrame(), getMaxFrame());
182	    this.frame = useCompositionFrameRate ? ((float) Math.floor(frameRaw)) : frameRaw;
183	    lastFrameTimeNs = 0;
184	    notifyUpdate();
185	  }
186	
187	  public void setMinFrame(int minFrame) {
188	    setMinAndMaxFrames(minFrame, (int) maxFrame);
189	  }
190	
191	  public void setMaxFrame(float maxFrame) {
192	    setMinAndMaxFrames(minFrame, maxFrame);
193	  }
194	
195	  public void setMinAndMaxFrames(float minFrame, float maxFrame) {
196	    if (minFrame > maxFrame) {
197	      throw new IllegalArgumentException(String.format("minFrame (%s) must be <= maxFrame (%s)", minFrame, maxFrame));
198	    }
199	    float compositionMinFrame = composition == null ? -Float.MAX_VALUE : composition.getStartFrame();
200	    float compositionMaxFrame = composition == null ? Float.MAX_VALUE : composition.getEndFrame();
201	    float newMinFrame = MiscUtils.clamp(minFrame, compositionMinFrame, compositionMaxFrame);
202	    float newMaxFrame = MiscUtils.clamp(maxFrame, compositionMinFrame, compositionMaxFrame);
203	    if (newMinFrame != this.minFrame || newMaxFrame != this.maxFrame) {
204	      this.minFrame = newMinFrame;
205	      this.maxFrame = newMaxFrame;
206	      setFrame((int) MiscUtils.clamp(frame, newMinFrame, newMaxFrame));
207	    }
208	  }
209	
210	  public void reverseAnimationSpeed() {
211	    setSpeed(-getSpeed());
212	  }
213	
214	  public void setSpeed(float speed) {
215	    this.speed = speed;
216	  }
217	
218	  /**
219	   * Returns the current speed. This will be affected by repeat mode REVERSE.
220	   */
221	  public float getSpeed() {
222	    return speed;
223	  }
224	
225	  @Override public void setRepeatMode(int value) {
226	    super.setRepeatMode(value);
227	    if (value != REVERSE && speedReversedForRepeatMode) {
228	      speedReversedForRepeatMode = false;
229	      reverseAnimationSpeed();
230	    }
231	  }
232	
233	  @MainThread
234	  public void playAnimation() {
235	    running = true;
236	    notifyStart(isReversed());
237	    setFrame((int) (isReversed() ? getMaxFrame() : getMinFrame()));
238	    lastFrameTimeNs = 0;
239	    repeatCount = 0;
240	    postFrameCallback();
241	  }
242	
243	  @MainThread
244	  public void endAnimation() {
245	    removeFrameCallback();
246	    notifyEnd(isReversed());
247	  }
248	
249	  @MainThread
250	  public void pauseAnimation() {
251	    removeFrameCallback();
252	    notifyPause();
253	  }
254	
255	  @MainThread
256	  public void resumeAnimation() {
257	    running = true;
258	    postFrameCallback();
259	    lastFrameTimeNs = 0;
260	    if (isReversed() && getFrame() == getMinFrame()) {
261	      setFrame(getMaxFrame());
262	    } else if (!isReversed() && getFrame() == getMaxFrame()) {
263	      setFrame(getMinFrame());
264	    }
265	    notifyResume();
266	  }
267	
268	  @MainThread
269	  @Override public void cancel() {
270	    notifyCancel();
271	    removeFrameCallback();
272	  }
273	
274	  private boolean isReversed() {
275	    return getSpeed() < 0;
276	  }
277	
278	  public float getMinFrame() {
279	    if (composition == null) {
280	      return 0;
281	    }
282	    return minFrame == Integer.MIN_VALUE ? composition.getStartFrame() : minFrame;
283	  }
284	
285	  public float getMaxFrame() {
286	    if (composition == null) {
287	      return 0;
288	    }
289	    return maxFrame == Integer.MAX_VALUE ? composition.getEndFrame() : maxFrame;
290	  }
291	
292	  @Override void notifyCancel() {
293	    super.notifyCancel();
294	    notifyEnd(isReversed());
295	  }
296	
297	  protected void postFrameCallback() {
298	    if (isRunning()) {
299	      removeFrameCallback(false);
300	      Choreographer.getInstance().postFrameCallback(this);
301	    }
302	  }
303	
304	  @MainThread
305	  protected void removeFrameCallback() {
306	    this.removeFrameCallback(true);
307	  }
308	
309	  @MainThread
310	  protected void removeFrameCallback(boolean stopRunning) {
311	    Choreographer.getInstance().removeFrameCallback(this);
312	    if (stopRunning) {
313	      running = false;
314	    }
315	  }
316	
317	  private void verifyFrame() {
318	    if (composition == null) {
319	      return;
320	    }
321	    if (frame < minFrame || frame > maxFrame) {
322	      throw new IllegalStateException(String.format("Frame must be [%f,%f]. It is %f", minFrame, maxFrame, frame));
323	    }
324	  }
325	}
