1	package com.airbnb.lottie.manager;
2	
3	import android.content.res.AssetManager;
4	import android.graphics.Typeface;
5	import android.graphics.drawable.Drawable;
6	import android.view.View;
7	
8	import androidx.annotation.Nullable;
9	
10	import com.airbnb.lottie.FontAssetDelegate;
11	import com.airbnb.lottie.model.Font;
12	import com.airbnb.lottie.model.MutablePair;
13	import com.airbnb.lottie.utils.Logger;
14	
15	import java.util.HashMap;
16	import java.util.Map;
17	
18	public class FontAssetManager {
19	  private final MutablePair<String> tempPair = new MutablePair<>();
20	
21	  /**
22	   * Pair is (fontName, fontStyle)
23	   */
24	  private final Map<MutablePair<String>, Typeface> fontMap = new HashMap<>();
25	  /**
26	   * Map of font families to their fonts. Necessary to create a font with a different style
27	   */
28	  private final Map<String, Typeface> fontFamilies = new HashMap<>();
29	  private final AssetManager assetManager;
30	  @Nullable private FontAssetDelegate delegate;
31	  private String defaultFontFileExtension = ".ttf";
32	
33	  public FontAssetManager(Drawable.Callback callback, @Nullable FontAssetDelegate delegate) {
34	    this.delegate = delegate;
35	    if (!(callback instanceof View)) {
36	      Logger.warning("LottieDrawable must be inside of a view for images to work.");
37	      assetManager = null;
38	      return;
39	    }
40	
41	    assetManager = ((View) callback).getContext().getAssets();
42	  }
43	
44	  public void setDelegate(@Nullable FontAssetDelegate assetDelegate) {
45	    this.delegate = assetDelegate;
46	  }
47	
48	  /**
49	   * Sets the default file extension (include the `.`).
50	   * <p>
51	   * e.g. `.ttf` `.otf`
52	   * <p>
53	   * Defaults to `.ttf`
54	   */
55	  @SuppressWarnings("unused") public void setDefaultFontFileExtension(String defaultFontFileExtension) {
56	    this.defaultFontFileExtension = defaultFontFileExtension;
57	  }
58	
59	  public Typeface getTypeface(Font font) {
60	    tempPair.set(font.getFamily(), font.getStyle());
61	    Typeface typeface = fontMap.get(tempPair);
62	    if (typeface != null) {
63	      return typeface;
64	    }
65	    Typeface typefaceWithDefaultStyle = getFontFamily(font);
66	    typeface = typefaceForStyle(typefaceWithDefaultStyle, font.getStyle());
67	    fontMap.put(tempPair, typeface);
68	    return typeface;
69	  }
70	
71	  private Typeface getFontFamily(Font font) {
72	    String fontFamily = font.getFamily();
73	    Typeface defaultTypeface = fontFamilies.get(fontFamily);
74	    if (defaultTypeface != null) {
75	      return defaultTypeface;
76	    }
77	
78	    Typeface typeface = null;
79	    String fontStyle = font.getStyle();
80	    String fontName = font.getName();
81	    if (delegate != null) {
82	      typeface = delegate.fetchFont(fontFamily, fontStyle, fontName);
83	      if (typeface == null) {
84	        typeface = delegate.fetchFont(fontFamily);
85	      }
86	    }
87	
88	    if (delegate != null && typeface == null) {
89	      String path = delegate.getFontPath(fontFamily, fontStyle, fontName);
90	      if (path == null) {
91	        path = delegate.getFontPath(fontFamily);
92	      }
93	      if (path != null) {
94	        typeface = Typeface.createFromAsset(assetManager, path);
95	      }
96	    }
97	
98	    if (font.getTypeface() != null) {
99	      return font.getTypeface();
100	    }
101	
102	    if (typeface == null) {
103	      String path = "fonts/" + fontFamily + defaultFontFileExtension;
104	      typeface = Typeface.createFromAsset(assetManager, path);
105	    }
106	
107	    fontFamilies.put(fontFamily, typeface);
108	    return typeface;
109	  }
110	
111	  private Typeface typefaceForStyle(Typeface typeface, String style) {
112	    int styleInt = Typeface.NORMAL;
113	    boolean containsItalic = style.contains("Italic");
114	    boolean containsBold = style.contains("Bold");
115	    if (containsItalic && containsBold) {
116	      styleInt = Typeface.BOLD_ITALIC;
117	    } else if (containsItalic) {
118	      styleInt = Typeface.ITALIC;
119	    } else if (containsBold) {
120	      styleInt = Typeface.BOLD;
121	    }
122	
123	    if (typeface.getStyle() == styleInt) {
124	      return typeface;
125	    }
126	
127	    return Typeface.create(typeface, styleInt);
128	  }
