23	public class ImageAssetManager {
24	  private static final Object bitmapHashLock = new Object();
25	  @Nullable private final Context context;
26	  private final String imagesFolder;
27	  @Nullable private ImageAssetDelegate delegate;
28	  private final Map<String, LottieImageAsset> imageAssets;
29	
30	  public ImageAssetManager(Drawable.Callback callback, String imagesFolder,
31	      ImageAssetDelegate delegate, Map<String, LottieImageAsset> imageAssets) {
32	    if (!TextUtils.isEmpty(imagesFolder) && imagesFolder.charAt(imagesFolder.length() - 1) != '/') {
33	      this.imagesFolder = imagesFolder + '/';
34	    } else {
35	      this.imagesFolder = imagesFolder;
36	    }
37	    this.imageAssets = imageAssets;
38	    setDelegate(delegate);
39	    if (!(callback instanceof View)) {
40	      context = null;
41	      return;
42	    }
43	
44	    context = ((View) callback).getContext().getApplicationContext();
45	  }
46	
47	  public void setDelegate(@Nullable ImageAssetDelegate assetDelegate) {
48	    this.delegate = assetDelegate;
49	  }
50	
51	  /**
52	   * Returns the previously set bitmap or null.
53	   */
54	  @Nullable public Bitmap updateBitmap(String id, @Nullable Bitmap bitmap) {
55	    if (bitmap == null) {
56	      LottieImageAsset asset = imageAssets.get(id);
57	      Bitmap ret = asset.getBitmap();
58	      asset.setBitmap(null);
59	      return ret;
60	    }
61	    Bitmap prevBitmap = imageAssets.get(id).getBitmap();
62	    putBitmap(id, bitmap);
63	    return prevBitmap;
64	  }
65	
66	  @Nullable public LottieImageAsset getImageAssetById(String id) {
67	    return imageAssets.get(id);
68	  }
69	
70	  @Nullable public Bitmap bitmapForId(String id) {
71	    LottieImageAsset asset = imageAssets.get(id);
72	    if (asset == null) {
73	      return null;
74	    }
75	
76	    Bitmap bitmap = asset.getBitmap();
77	    if (bitmap != null) {
78	      return bitmap;
79	    }
80	
81	    if (delegate != null) {
82	      bitmap = delegate.fetchBitmap(asset);
83	      if (bitmap != null) {
84	        putBitmap(id, bitmap);
85	      }
86	      return bitmap;
87	    }
88	    Context context = this.context;
89	    if (context == null) {
90	      // If there is no context, the image has to be embedded or provided via
91	      // a delegate.
92	      return null;
93	    }
94	
95	    String filename = asset.getFileName();
96	    BitmapFactory.Options opts = new BitmapFactory.Options();
97	    opts.inScaled = true;
98	    opts.inDensity = 160;
99	
100	    if (filename.startsWith("data:") && filename.indexOf("base64,") > 0) {
101	      // Contents look like a base64 data URI, with the format data:image/png;base64,<data>.
102	      byte[] data;
103	      try {
104	        data = Base64.decode(filename.substring(filename.indexOf(',') + 1), Base64.DEFAULT);
105	      } catch (IllegalArgumentException e) {
106	        Logger.warning("data URL did not have correct base64 format.", e);
107	        return null;
108	      }
109	
110	      try {
111	        bitmap = BitmapFactory.decodeByteArray(data, 0, data.length, opts);
112	      } catch (IllegalArgumentException e) {
113	        Logger.warning("Unable to decode image `" + id + "`.", e);
114	        return null;
115	      }
116	
117	      if (bitmap == null) {
118	        Logger.warning("Decoded image `" + id + "` is null.");
119	        return null;
120	      }
121	
122	      Bitmap resizedBitmap = Utils.resizeBitmapIfNeeded(bitmap, asset.getWidth(), asset.getHeight());
123	      return putBitmap(id, resizedBitmap);
124	    }
125	
126	    InputStream is;
127	    try {
128	      if (TextUtils.isEmpty(imagesFolder)) {
129	        throw new IllegalStateException("You must set an images folder before loading an image." +
130	            " Set it with LottieComposition#setImagesFolder or LottieDrawable#setImagesFolder");
131	      }
132	      is = context.getAssets().open(imagesFolder + filename);
133	    } catch (IOException e) {
134	      Logger.warning("Unable to open asset.", e);
135	      return null;
136	    }
137	
138	    try {
139	      bitmap = BitmapFactory.decodeStream(is, null, opts);
140	    } catch (IllegalArgumentException e) {
141	      Logger.warning("Unable to decode image `" + id + "`.", e);
142	      return null;
143	    }
144	    if (bitmap == null) {
145	      Logger.warning("Decoded image `" + id + "` is null.");
146	      return null;
147	    }
148	    bitmap = Utils.resizeBitmapIfNeeded(bitmap, asset.getWidth(), asset.getHeight());
149	    return putBitmap(id, bitmap);
150	  }
151	
152	  public boolean hasSameContext(Context context) {
153	    if (context == null) {
154	      return this.context == null;
155	    }
156	    Context contextToCompare = this.context instanceof Application ? context.getApplicationContext() : context;
157	    return contextToCompare == this.context;
158	  }
159	
160	  private Bitmap putBitmap(String key, @Nullable Bitmap bitmap) {
161	    synchronized (bitmapHashLock) {
162	      imageAssets.get(key).setBitmap(bitmap);
163	      return bitmap;
164	    }
165	  }
166	}
