634	  private void setCompositionTask(LottieTask<LottieComposition> compositionTask) {
635	    LottieResult<LottieComposition> result = compositionTask.getResult();
636	    LottieDrawable lottieDrawable = this.lottieDrawable;
637	    if (result != null && lottieDrawable == getDrawable() && lottieDrawable.getComposition() == result.getValue()) {
638	      return;
639	    }
640	    userActionsTaken.add(UserActionTaken.SET_ANIMATION);
641	    clearComposition();
642	    cancelLoaderTask();
643	    this.compositionTask = compositionTask
644	        .addListener(loadedListener)
645	        .addFailureListener(wrappedFailureListener);
646	  }
647	
648	  private void cancelLoaderTask() {
649	    if (compositionTask != null) {
650	      compositionTask.removeListener(loadedListener);
651	      compositionTask.removeFailureListener(wrappedFailureListener);
652	    }
653	  }
