22	
23	@RestrictTo(RestrictTo.Scope.LIBRARY)
24	public class NetworkFetcher {
25	
26	  @Nullable
27	  private final NetworkCache networkCache;
28	  @NonNull
29	  private final LottieNetworkFetcher fetcher;
30	
31	  public NetworkFetcher(@Nullable NetworkCache networkCache, @NonNull LottieNetworkFetcher fetcher) {
32	    this.networkCache = networkCache;
33	    this.fetcher = fetcher;
34	  }
35	
36	  @NonNull
37	  @WorkerThread
38	  public LottieResult<LottieComposition> fetchSync(Context context, @NonNull String url, @Nullable String cacheKey) {
39	    LottieComposition result = fetchFromCache(context, url, cacheKey);
40	    if (result != null) {
41	      return new LottieResult<>(result);
42	    }
43	
44	    Logger.debug("Animation for " + url + " not found in cache. Fetching from network.");
45	
46	    return fetchFromNetwork(context, url, cacheKey);
47	  }
48	
49	  @Nullable
50	  @WorkerThread
51	  private LottieComposition fetchFromCache(Context context, @NonNull String url, @Nullable String cacheKey) {
52	    if (cacheKey == null || networkCache == null) {
53	      return null;
54	    }
55	    Pair<FileExtension, InputStream> cacheResult = networkCache.fetch(url);
56	    if (cacheResult == null) {
57	      return null;
58	    }
59	
60	    FileExtension extension = cacheResult.first;
61	    InputStream inputStream = cacheResult.second;
62	    LottieResult<LottieComposition> result;
63	    switch (extension) {
64	      case ZIP:
65	        result = LottieCompositionFactory.fromZipStreamSync(context, new ZipInputStream(inputStream), cacheKey);
66	        break;
67	      case GZIP:
68	        try {
69	          result = LottieCompositionFactory.fromJsonInputStreamSync(new GZIPInputStream(inputStream), cacheKey);
70	        } catch (IOException e) {
71	          result = new LottieResult<>(e);
72	        }
73	        break;
74	      default:
75	        result = LottieCompositionFactory.fromJsonInputStreamSync(inputStream, cacheKey);
76	    }
77	    return result.getValue();
78	  }
79	
80	  @NonNull
81	  @WorkerThread
82	  private LottieResult<LottieComposition> fetchFromNetwork(Context context, @NonNull String url, @Nullable String cacheKey) {
83	    Logger.debug("Fetching " + url);
84	
85	    LottieFetchResult fetchResult = null;
86	    try {
87	      fetchResult = fetcher.fetchSync(url);
88	      if (fetchResult.isSuccessful()) {
89	        InputStream inputStream = fetchResult.bodyByteStream();
90	        String contentType = fetchResult.contentType();
91	        LottieResult<LottieComposition> result = fromInputStream(context, url, inputStream, contentType, cacheKey);
92	        Logger.debug("Completed fetch from network. Success: " + (result.getValue() != null));
93	        return result;
94	      } else {
95	        return new LottieResult<>(new IllegalArgumentException(fetchResult.error()));
96	      }
97	    } catch (Exception e) {
98	      return new LottieResult<>(e);
99	    } finally {
100	      if (fetchResult != null) {
101	        try {
102	          fetchResult.close();
103	        } catch (IOException e) {
104	          Logger.warning("LottieFetchResult close failed ", e);
105	        }
106	      }
107	    }
108	  }
109	
110	  @NonNull
111	  private LottieResult<LottieComposition> fromInputStream(Context context, @NonNull String url, @NonNull InputStream inputStream, @Nullable String contentType,
112	      @Nullable String cacheKey) throws IOException {
113	    FileExtension extension;
114	    LottieResult<LottieComposition> result;
115	    if (contentType == null) {
116	      // Assume JSON for best effort parsing. If it fails, it will just deliver the parse exception
117	      // in the result which is more useful than failing here.
118	      contentType = "application/json";
119	    }
120	    String baseUrl = url.split("\\?")[0];
121	    if (contentType.contains("application/zip") ||
122	        contentType.contains("application/x-zip") ||
123	        contentType.contains("application/x-zip-compressed") ||
124	        baseUrl.endsWith(".lottie")) {
125	      Logger.debug("Handling zip response.");
126	      extension = FileExtension.ZIP;
127	      result = fromZipStream(context, url, inputStream, cacheKey);
128	    } else if (contentType.contains("application/gzip") ||
129	        contentType.contains("application/x-gzip") ||
130	        baseUrl.endsWith(".tgs")) {
131	      Logger.debug("Handling gzip response.");
132	      extension = FileExtension.GZIP;
133	      result = fromGzipStream(url, inputStream, cacheKey);
134	    } else {
135	      Logger.debug("Received json response.");
136	      extension = FileExtension.JSON;
137	      result = fromJsonStream(url, inputStream, cacheKey);
138	    }
139	
140	    if (cacheKey != null && result.getValue() != null && networkCache != null) {
141	      networkCache.renameTempFile(url, extension);
142	    }
143	
144	    return result;
145	  }
146	
147	  @NonNull
148	  private LottieResult<LottieComposition> fromZipStream(Context context, @NonNull String url, @NonNull InputStream inputStream, @Nullable String cacheKey)
149	      throws IOException {
150	    if (cacheKey == null || networkCache == null) {
151	      return LottieCompositionFactory.fromZipStreamSync(context, new ZipInputStream(inputStream), null);
152	    }
153	    File file = networkCache.writeTempCacheFile(url, inputStream, FileExtension.ZIP);
154	    return LottieCompositionFactory.fromZipStreamSync(context, new ZipInputStream(new FileInputStream(file)), url);
155	  }
156	
157	  @NonNull
158	  private LottieResult<LottieComposition> fromGzipStream(@NonNull String url, @NonNull InputStream inputStream, @Nullable String cacheKey)
159	      throws IOException {
160	    if (cacheKey == null || networkCache == null) {
161	      return LottieCompositionFactory.fromJsonInputStreamSync(new GZIPInputStream(inputStream), null);
162	    }
163	    File file = networkCache.writeTempCacheFile(url, inputStream, FileExtension.GZIP);
164	    return LottieCompositionFactory.fromJsonInputStreamSync(new GZIPInputStream(new FileInputStream(file)), url);
165	  }
