167	  @NonNull
168	  private LottieResult<LottieComposition> fromJsonStream(@NonNull String url, @NonNull InputStream inputStream, @Nullable String cacheKey)
169	      throws IOException {
170	    if (cacheKey == null || networkCache == null) {
171	      return LottieCompositionFactory.fromJsonInputStreamSync(inputStream, null);
172	    }
173	    File file = networkCache.writeTempCacheFile(url, inputStream, FileExtension.JSON);
174	    return LottieCompositionFactory.fromJsonInputStreamSync(new FileInputStream(file.getAbsolutePath()), url);
175	  }
