1	package com.airbnb.lottie.parser;
2	
3	import android.graphics.PointF;
4	
5	import com.airbnb.lottie.model.CubicCurveData;
6	import com.airbnb.lottie.model.content.ShapeData;
7	import com.airbnb.lottie.parser.moshi.JsonReader;
8	import com.airbnb.lottie.utils.MiscUtils;
9	
10	import java.io.IOException;
11	import java.util.ArrayList;
12	import java.util.Collections;
13	import java.util.List;
14	
15	public class ShapeDataParser implements ValueParser<ShapeData> {
16	  public static final ShapeDataParser INSTANCE = new ShapeDataParser();
17	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
18	      "c",
19	      "v",
20	      "i",
21	      "o"
22	  );
23	
24	  private ShapeDataParser() {
25	  }
26	
27	  @Override
28	  public ShapeData parse(JsonReader reader, float scale) throws IOException {
29	    // Sometimes the points data is in a array of length 1. Sometimes the data is at the top
30	    // level.
31	    if (reader.peek() == JsonReader.Token.BEGIN_ARRAY) {
32	      reader.beginArray();
33	    }
34	
35	    boolean closed = false;
36	    List<PointF> pointsArray = null;
37	    List<PointF> inTangents = null;
38	    List<PointF> outTangents = null;
39	    reader.beginObject();
40	
41	    while (reader.hasNext()) {
42	      switch (reader.selectName(NAMES)) {
43	        case 0:
44	          closed = reader.nextBoolean();
45	          break;
46	        case 1:
47	          pointsArray = JsonUtils.jsonToPoints(reader, scale);
48	          break;
49	        case 2:
50	          inTangents = JsonUtils.jsonToPoints(reader, scale);
51	          break;
52	        case 3:
53	          outTangents = JsonUtils.jsonToPoints(reader, scale);
54	          break;
55	        default:
56	          reader.skipName();
57	          reader.skipValue();
58	      }
59	    }
60	
61	    reader.endObject();
62	
63	    if (reader.peek() == JsonReader.Token.END_ARRAY) {
64	      reader.endArray();
65	    }
66	
67	    if (pointsArray == null || inTangents == null || outTangents == null) {
68	      throw new IllegalArgumentException("Shape data was missing information.");
69	    }
70	
71	    if (pointsArray.isEmpty()) {
72	      return new ShapeData(new PointF(), false, Collections.<CubicCurveData>emptyList());
73	    }
74	
75	    int length = pointsArray.size();
76	    PointF vertex = pointsArray.get(0);
77	    PointF initialPoint = vertex;
78	    List<CubicCurveData> curves = new ArrayList<>(length);
79	
80	    for (int i = 1; i < length; i++) {
81	      vertex = pointsArray.get(i);
82	      PointF previousVertex = pointsArray.get(i - 1);
83	      PointF cp1 = outTangents.get(i - 1);
84	      PointF cp2 = inTangents.get(i);
85	      PointF shapeCp1 = MiscUtils.addPoints(previousVertex, cp1);
86	      PointF shapeCp2 = MiscUtils.addPoints(vertex, cp2);
87	      curves.add(new CubicCurveData(shapeCp1, shapeCp2, vertex));
88	    }
89	
90	    if (closed) {
91	      vertex = pointsArray.get(0);
92	      PointF previousVertex = pointsArray.get(length - 1);
93	      PointF cp1 = outTangents.get(length - 1);
94	      PointF cp2 = inTangents.get(0);
95	
96	      PointF shapeCp1 = MiscUtils.addPoints(previousVertex, cp1);
97	      PointF shapeCp2 = MiscUtils.addPoints(vertex, cp2);
98	
99	      curves.add(new CubicCurveData(shapeCp1, shapeCp2, vertex));
100	    }
101	    return new ShapeData(initialPoint, closed, curves);
102	  }
