2	
3	import android.graphics.Rect;
4	
5	import androidx.collection.LongSparseArray;
6	import androidx.collection.SparseArrayCompat;
7	
8	import com.airbnb.lottie.LottieComposition;
9	import com.airbnb.lottie.LottieImageAsset;
10	import com.airbnb.lottie.model.Font;
11	import com.airbnb.lottie.model.FontCharacter;
12	import com.airbnb.lottie.model.Marker;
13	import com.airbnb.lottie.model.layer.Layer;
14	import com.airbnb.lottie.parser.moshi.JsonReader;
15	import com.airbnb.lottie.utils.Logger;
16	import com.airbnb.lottie.utils.Utils;
17	
18	import java.io.IOException;
19	import java.util.ArrayList;
20	import java.util.HashMap;
21	import java.util.List;
22	import java.util.Map;
23	
24	
25	public class LottieCompositionMoshiParser {
26	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
27	      "w", // 0
28	      "h", // 1
29	      "ip", // 2
30	      "op", // 3
31	      "fr", // 4
32	      "v", // 5
33	      "layers", // 6
34	      "assets", // 7
35	      "fonts", // 8
36	      "chars", // 9
37	      "markers" // 10
38	  );
39	
40	  public static LottieComposition parse(JsonReader reader) throws IOException {
41	    float scale = Utils.dpScale();
42	    float startFrame = 0f;
43	    float endFrame = 0f;
44	    float frameRate = 0f;
45	    final LongSparseArray<Layer> layerMap = new LongSparseArray<>();
46	    final List<Layer> layers = new ArrayList<>();
47	    int unscaledWidth = 0;
48	    int unscaledHeight = 0;
49	    Map<String, List<Layer>> precomps = new HashMap<>();
50	    Map<String, LottieImageAsset> images = new HashMap<>();
51	    Map<String, Font> fonts = new HashMap<>();
52	    List<Marker> markers = new ArrayList<>();
53	    SparseArrayCompat<FontCharacter> characters = new SparseArrayCompat<>();
54	
55	    LottieComposition composition = new LottieComposition();
56	    reader.beginObject();
57	    while (reader.hasNext()) {
58	      switch (reader.selectName(NAMES)) {
59	        case 0:
60	          // width/height should be an int. However, some exporters export doubles and we don't want to crash.
61	          // Given that this is non-spec compliant, truncating to int is probably better than rounding to avoid
62	          // the extra work in the vast majority of cases.
63	          unscaledWidth = (int) reader.nextDouble();
64	          break;
65	        case 1:
66	          unscaledHeight = (int) reader.nextDouble();
67	          break;
68	        case 2:
69	          startFrame = (float) reader.nextDouble();
70	          break;
71	        case 3:
72	          endFrame = (float) reader.nextDouble() - 0.01f;
73	          break;
74	        case 4:
75	          frameRate = (float) reader.nextDouble();
76	          break;
77	        case 5:
78	          String version = reader.nextString();
79	          String[] versions = version.split("\\.");
80	          int majorVersion = Integer.parseInt(versions[0]);
81	          int minorVersion = Integer.parseInt(versions[1]);
82	          int patchVersion = Integer.parseInt(versions[2]);
83	          if (!Utils.isAtLeastVersion(majorVersion, minorVersion, patchVersion,
84	              4, 4, 0)) {
85	            composition.addWarning("Lottie only supports bodymovin >= 4.4.0");
86	          }
87	          break;
88	        case 6:
89	          parseLayers(reader, composition, layers, layerMap);
90	          break;
91	        case 7:
92	          parseAssets(reader, composition, precomps, images);
93	          break;
94	        case 8:
95	          parseFonts(reader, fonts);
96	          break;
97	        case 9:
98	          parseChars(reader, composition, characters);
99	          break;
100	        case 10:
101	          parseMarkers(reader, markers);
102	          break;
103	        default:
104	          reader.skipName();
105	          reader.skipValue();
106	      }
107	    }
108	    int scaledWidth = (int) (unscaledWidth * scale);
109	    int scaledHeight = (int) (unscaledHeight * scale);
110	    Rect bounds = new Rect(0, 0, scaledWidth, scaledHeight);
111	
112	    composition.init(bounds, startFrame, endFrame, frameRate, layers, layerMap, precomps,
113	        images, Utils.dpScale(), characters, fonts, markers, unscaledWidth, unscaledHeight);
114	
115	    return composition;
116	  }
117	
118	  private static void parseLayers(JsonReader reader, LottieComposition composition,
119	      List<Layer> layers, LongSparseArray<Layer> layerMap) throws IOException {
120	    int imageCount = 0;
121	    reader.beginArray();
122	    while (reader.hasNext()) {
123	      Layer layer = LayerParser.parse(reader, composition);
124	      if (layer.getLayerType() == Layer.LayerType.IMAGE) {
125	        imageCount++;
126	      }
127	      layers.add(layer);
128	      layerMap.put(layer.getId(), layer);
129	
130	      if (imageCount > 4) {
131	        Logger.warning("You have " + imageCount + " images. Lottie should primarily be " +
132	            "used with shapes. If you are using Adobe Illustrator, convert the Illustrator layers" +
133	            " to shape layers.");
134	      }
135	    }
136	    reader.endArray();
137	  }
138	
139	
140	  static JsonReader.Options ASSETS_NAMES = JsonReader.Options.of(
141	      "id", // 0
142	      "layers", // 1
143	      "w", // 2
144	      "h", // 3
145	      "p", // 4
146	      "u" // 5
147	  );
148	
149	  private static void parseAssets(JsonReader reader, LottieComposition composition,
150	      Map<String, List<Layer>> precomps, Map<String, LottieImageAsset> images) throws IOException {
151	    reader.beginArray();
152	    while (reader.hasNext()) {
153	      String id = null;
154	      // For precomps
155	      List<Layer> layers = new ArrayList<>();
156	      LongSparseArray<Layer> layerMap = new LongSparseArray<>();
157	      // For images
158	      int width = 0;
159	      int height = 0;
160	      String imageFileName = null;
161	      String relativeFolder = null;
162	      reader.beginObject();
163	      while (reader.hasNext()) {
164	        switch (reader.selectName(ASSETS_NAMES)) {
165	          case 0:
166	            id = reader.nextString();
167	            break;
168	          case 1:
169	            reader.beginArray();
170	            while (reader.hasNext()) {
171	              Layer layer = LayerParser.parse(reader, composition);
172	              layerMap.put(layer.getId(), layer);
173	              layers.add(layer);
174	            }
175	            reader.endArray();
176	            break;
177	          case 2:
178	            width = reader.nextInt();
179	            break;
180	          case 3:
181	            height = reader.nextInt();
182	            break;
183	          case 4:
184	            imageFileName = reader.nextString();
185	            break;
186	          case 5:
187	            relativeFolder = reader.nextString();
188	            break;
189	          default:
190	            reader.skipName();
191	            reader.skipValue();
192	        }
193	      }
194	      reader.endObject();
195	      if (imageFileName != null) {
196	        LottieImageAsset image =
197	            new LottieImageAsset(width, height, id, imageFileName, relativeFolder);
198	        images.put(image.getId(), image);
199	      } else {
200	        precomps.put(id, layers);
201	      }
202	    }
203	    reader.endArray();
204	  }
205	
206	  private static final JsonReader.Options FONT_NAMES = JsonReader.Options.of("list");
207	
208	  private static void parseFonts(JsonReader reader, Map<String, Font> fonts) throws IOException {
209	    reader.beginObject();
210	    while (reader.hasNext()) {
211	      switch (reader.selectName(FONT_NAMES)) {
212	        case 0:
213	          reader.beginArray();
214	          while (reader.hasNext()) {
215	            Font font = FontParser.parse(reader);
216	            fonts.put(font.getName(), font);
217	          }
218	          reader.endArray();
219	          break;
220	        default:
221	          reader.skipName();
222	          reader.skipValue();
223	      }
224	    }
225	    reader.endObject();
226	  }
227	
228	  private static void parseChars(
229	      JsonReader reader, LottieComposition composition,
230	      SparseArrayCompat<FontCharacter> characters) throws IOException {
231	    reader.beginArray();
232	    while (reader.hasNext()) {
233	      FontCharacter character = FontCharacterParser.parse(reader, composition);
234	      characters.put(character.hashCode(), character);
235	    }
236	    reader.endArray();
237	  }
238	
239	  private static final JsonReader.Options MARKER_NAMES = JsonReader.Options.of(
240	      "cm",
241	      "tm",
242	      "dr"
243	  );
244	
245	  private static void parseMarkers(JsonReader reader, List<Marker> markers) throws IOException {
246	    reader.beginArray();
247	    while (reader.hasNext()) {
248	      String comment = null;
249	      float frame = 0f;
250	      float durationFrames = 0f;
251	      reader.beginObject();
252	      while (reader.hasNext()) {
253	        switch (reader.selectName(MARKER_NAMES)) {
254	          case 0:
255	            comment = reader.nextString();
256	            break;
257	          case 1:
258	            frame = (float) reader.nextDouble();
259	            break;
260	          case 2:
261	            durationFrames = (float) reader.nextDouble();
262	            break;
263	          default:
264	            reader.skipName();
265	            reader.skipValue();
266	        }
267	      }
268	      reader.endObject();
269	      markers.add(new Marker(comment, frame, durationFrames));
270	    }
271	    reader.endArray();
272	  }
273	}
