342	
343	    SavedState ss = (SavedState) state;
344	    super.onRestoreInstanceState(ss.getSuperState());
345	    animationName = ss.animationName;
346	    if (!userActionsTaken.contains(UserActionTaken.SET_ANIMATION) && !TextUtils.isEmpty(animationName)) {
347	      setAnimation(animationName);
348	    }
349	    animationResId = ss.animationResId;
350	    if (!userActionsTaken.contains(UserActionTaken.SET_ANIMATION) && animationResId != 0) {
351	      setAnimation(animationResId);
352	    }
353	    if (!userActionsTaken.contains(UserActionTaken.SET_PROGRESS)) {
354	      setProgressInternal(ss.progress, false);
355	    }
356	    if (!userActionsTaken.contains(UserActionTaken.PLAY_OPTION) && ss.isAnimating) {
357	      playAnimation();
358	    }
359	    if (!userActionsTaken.contains(UserActionTaken.SET_IMAGE_ASSETS)) {
360	      setImageAssetsFolder(ss.imageAssetsFolder);
361	    }
362	    if (!userActionsTaken.contains(UserActionTaken.SET_REPEAT_MODE)) {
363	      setRepeatMode(ss.repeatMode);
364	    }
365	    if (!userActionsTaken.contains(UserActionTaken.SET_REPEAT_COUNT)) {
366	      setRepeatCount(ss.repeatCount);
367	    }
368	  }
