3	import android.graphics.PointF;
4	
5	import com.airbnb.lottie.value.Keyframe;
6	
7	import java.util.List;
8	
9	public class PointKeyframeAnimation extends KeyframeAnimation<PointF> {
10	  private final PointF point = new PointF();
11	
12	  public PointKeyframeAnimation(List<Keyframe<PointF>> keyframes) {
13	    super(keyframes);
14	  }
15	
16	  @Override public PointF getValue(Keyframe<PointF> keyframe, float keyframeProgress) {
17	    return getValue(keyframe, keyframeProgress, keyframeProgress, keyframeProgress);
18	  }
19	
20	  @Override protected PointF getValue(Keyframe<PointF> keyframe, float linearKeyframeProgress, float xKeyframeProgress, float yKeyframeProgress) {
21	    if (keyframe.startValue == null || keyframe.endValue == null) {
22	      throw new IllegalStateException("Missing values for keyframe.");
23	    }
24	
25	    PointF startPoint = keyframe.startValue;
26	    PointF endPoint = keyframe.endValue;
27	
28	    if (valueCallback != null) {
29	      //noinspection ConstantConditions
30	      PointF value = valueCallback.getValueInternal(keyframe.startFrame, keyframe.endFrame, startPoint,
31	          endPoint, linearKeyframeProgress, getLinearCurrentKeyframeProgress(), getProgress());
32	      if (value != null) {
33	        return value;
34	      }
35	    }
36	
37	    point.set(startPoint.x + xKeyframeProgress * (endPoint.x - startPoint.x),
38	        startPoint.y + yKeyframeProgress * (endPoint.y - startPoint.y));
39	    return point;
40	  }
41	}
