28	          keyframeProgress, getLinearCurrentKeyframeProgress(), getProgress());
29	      if (value != null) {
30	        return value;
31	      }
32	    }
33	
34	    scaleXY.set(
35	        MiscUtils.lerp(startTransform.getScaleX(), endTransform.getScaleX(), keyframeProgress),
36	        MiscUtils.lerp(startTransform.getScaleY(), endTransform.getScaleY(), keyframeProgress)
37	    );
38	    return scaleXY;
39	  }
40	}
