3	
4	import com.airbnb.lottie.LottieComposition;
5	import com.airbnb.lottie.model.content.ContentModel;
6	import com.airbnb.lottie.model.content.ShapeGroup;
7	import com.airbnb.lottie.parser.moshi.JsonReader;
8	
9	import java.io.IOException;
10	import java.util.ArrayList;
11	import java.util.List;
12	
13	class ShapeGroupParser {
14	
15	  private ShapeGroupParser() {
16	  }
17	
18	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
19	      "nm",
20	      "hd",
21	      "it"
22	  );
23	
24	  static ShapeGroup parse(
25	      JsonReader reader, LottieComposition composition) throws IOException {
26	    String name = null;
27	    boolean hidden = false;
28	    List<ContentModel> items = new ArrayList<>();
29	
30	    while (reader.hasNext()) {
31	      switch (reader.selectName(NAMES)) {
32	        case 0:
33	          name = reader.nextString();
34	          break;
35	        case 1:
36	          hidden = reader.nextBoolean();
37	          break;
38	        case 2:
39	          reader.beginArray();
40	          while (reader.hasNext()) {
41	            ContentModel newItem = ContentModelParser.parse(reader, composition);
42	            if (newItem != null) {
43	              items.add(newItem);
44	            }
45	          }
46	          reader.endArray();
47	          break;
48	        default:
49	          reader.skipValue();
50	      }
51	    }
52	
53	    return new ShapeGroup(name, items, hidden);
54	  }
55	}
