3	import com.airbnb.lottie.LottieComposition;
4	import com.airbnb.lottie.model.FontCharacter;
5	import com.airbnb.lottie.model.content.ShapeGroup;
6	import com.airbnb.lottie.parser.moshi.JsonReader;
7	
8	import java.io.IOException;
9	import java.util.ArrayList;
10	import java.util.List;
11	
12	class FontCharacterParser {
13	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
14	      "ch",
15	      "size",
16	      "w",
17	      "style",
18	      "fFamily",
19	      "data"
20	  );
21	  private static final JsonReader.Options DATA_NAMES = JsonReader.Options.of("shapes");
22	
23	  private FontCharacterParser() {
24	  }
25	
26	  static FontCharacter parse(
27	      JsonReader reader, LottieComposition composition) throws IOException {
28	    char character = '\0';
29	    double size = 0;
30	    double width = 0;
31	    String style = null;
32	    String fontFamily = null;
33	    List<ShapeGroup> shapes = new ArrayList<>();
34	
35	    reader.beginObject();
36	    while (reader.hasNext()) {
37	      switch (reader.selectName(NAMES)) {
38	        case 0:
39	          character = reader.nextString().charAt(0);
40	          break;
41	        case 1:
42	          size = reader.nextDouble();
43	          break;
44	        case 2:
45	          width = reader.nextDouble();
46	          break;
47	        case 3:
48	          style = reader.nextString();
49	          break;
50	        case 4:
51	          fontFamily = reader.nextString();
52	          break;
53	        case 5:
54	          reader.beginObject();
55	          while (reader.hasNext()) {
56	            switch (reader.selectName(DATA_NAMES)) {
57	              case 0:
58	                reader.beginArray();
59	                while (reader.hasNext()) {
60	                  shapes.add((ShapeGroup) ContentModelParser.parse(reader, composition));
61	                }
62	                reader.endArray();
63	                break;
64	              default:
65	                reader.skipName();
66	                reader.skipValue();
67	            }
68	          }
69	          reader.endObject();
70	          break;
71	        default:
72	          reader.skipName();
73	          reader.skipValue();
74	      }
75	    }
76	    reader.endObject();
77	
78	    return new FontCharacter(shapes, character, size, width, style, fontFamily);
79	  }
80	}
