34	  // deserialzie the data so we have to parse everything in order
35	  public PointF pathCp1 = null;
36	  public PointF pathCp2 = null;
37	
38	
39	  public Keyframe(@SuppressWarnings("NullableProblems") LottieComposition composition,
40	      @Nullable T startValue, @Nullable T endValue,
41	      @Nullable Interpolator interpolator, float startFrame, @Nullable Float endFrame) {
42	    this.composition = composition;
43	    this.startValue = startValue;
