52	  public Keyframe(@SuppressWarnings("NullableProblems") LottieComposition composition,
53	      @Nullable T startValue, @Nullable T endValue,
54	      @Nullable Interpolator xInterpolator, @Nullable Interpolator yInterpolator, float startFrame, @Nullable Float endFrame) {
55	    this.composition = composition;
56	    this.startValue = startValue;
57	    this.endValue = endValue;
58	    interpolator = null;
59	    this.xInterpolator = xInterpolator;
60	    this.yInterpolator = yInterpolator;
61	    this.startFrame = startFrame;
62	    this.endFrame = endFrame;
63	  }
64	
65	  protected Keyframe(@SuppressWarnings("NullableProblems") LottieComposition composition,
66	      @Nullable T startValue, @Nullable T endValue,
67	      @Nullable Interpolator interpolator, @Nullable Interpolator xInterpolator, @Nullable Interpolator yInterpolator,
68	      float startFrame, @Nullable Float endFrame) {
69	    this.composition = composition;
70	    this.startValue = startValue;
71	    this.endValue = endValue;
72	    this.interpolator = interpolator;
73	    this.xInterpolator = xInterpolator;
74	    this.yInterpolator = yInterpolator;
75	    this.startFrame = startFrame;
76	    this.endFrame = endFrame;
77	  }
78	
79	  /**
80	   * Non-animated value.
81	   */
82	  public Keyframe(@SuppressWarnings("NullableProblems") T value) {
83	    composition = null;
84	    startValue = value;
85	    endValue = value;
86	    interpolator = null;
87	    xInterpolator = null;
88	    yInterpolator = null;
89	    startFrame = Float.MIN_VALUE;
90	    endFrame = Float.MAX_VALUE;
91	  }
92	
93	  private Keyframe(T startValue, T endValue) {
94	    composition = null;
95	    this.startValue = startValue;
96	    this.endValue = endValue;
97	    interpolator = null;
98	    xInterpolator = null;
99	    yInterpolator = null;
100	    startFrame = Float.MIN_VALUE;
101	    endFrame = Float.MAX_VALUE;
102	  }
103	
104	  public Keyframe<T> copyWith(T startValue, T endValue) {
105	    return new Keyframe<T>(startValue, endValue);
106	  }
107	
108	  public float getStartProgress() {
109	    if (composition == null) {
110	      return 0f;
111	    }
112	    if (startProgress == Float.MIN_VALUE) {
113	      startProgress = (startFrame - composition.getStartFrame()) / composition.getDurationFrames();
114	    }
115	    return startProgress;
116	  }
117	
118	  public float getEndProgress() {
119	    if (composition == null) {
120	      return 1f;
121	    }
122	    if (endProgress == Float.MIN_VALUE) {
123	      if (endFrame == null) {
124	        endProgress = 1f;
125	      } else {
126	        float startProgress = getStartProgress();
127	        float durationFrames = endFrame - startFrame;
128	        double durationProgress = durationFrames / (double) composition.getDurationFrames();
129	        endProgress = (float) (startProgress + durationProgress);
130	      }
131	    }
132	    return endProgress;
133	  }
134	
135	  public boolean isStatic() {
136	    return interpolator == null && xInterpolator == null && yInterpolator == null;
137	  }
138	
139	  public boolean containsProgress(@FloatRange(from = 0f, to = 1f) float progress) {
140	    return progress >= getStartProgress() && progress < getEndProgress();
141	  }
142	
143	  /**
144	   * Optimization to avoid autoboxing.
145	   */
146	  public float getStartValueFloat() {
147	    if (startValueFloat == UNSET_FLOAT) {
148	      startValueFloat = (float) (Float) startValue;
149	    }
150	    return startValueFloat;
151	  }
152	
153	  /**
154	   * Optimization to avoid autoboxing.
155	   */
156	  public float getEndValueFloat() {
157	    if (endValueFloat == UNSET_FLOAT) {
158	      endValueFloat = (float) (Float) endValue;
159	    }
160	    return endValueFloat;
161	  }
