169	    }
170	    return startValueInt;
171	  }
172	
173	  /**
174	   * Optimization to avoid autoboxing.
175	   */
176	  public int getEndValueInt() {
177	    if (endValueInt == UNSET_INT) {
178	      endValueInt = (int) (Integer) endValue;
179	    }
180	    return endValueInt;
181	  }
