6	import android.graphics.Matrix;
7	import android.graphics.Paint;
8	import android.graphics.Path;
9	import android.graphics.RectF;
10	
11	import androidx.annotation.Nullable;
12	
13	import com.airbnb.lottie.LottieDrawable;
14	import com.airbnb.lottie.LottieProperty;
15	import com.airbnb.lottie.animation.LPaint;
16	import com.airbnb.lottie.animation.keyframe.BaseKeyframeAnimation;
17	import com.airbnb.lottie.animation.keyframe.ValueCallbackKeyframeAnimation;
18	import com.airbnb.lottie.utils.DropShadow;
19	import com.airbnb.lottie.value.LottieValueCallback;
20	
21	public class SolidLayer extends BaseLayer {
22	
23	  private final RectF rect = new RectF();
24	  private final Paint paint = new LPaint();
25	  private final float[] points = new float[8];
26	  private final Path path = new Path();
27	  private final Layer layerModel;
28	  @Nullable private BaseKeyframeAnimation<ColorFilter, ColorFilter> colorFilterAnimation;
29	  @Nullable private BaseKeyframeAnimation<Integer, Integer> colorAnimation;
30	
31	  SolidLayer(LottieDrawable lottieDrawable, Layer layerModel) {
32	    super(lottieDrawable, layerModel);
33	    this.layerModel = layerModel;
34	
35	    paint.setAlpha(0);
36	    paint.setStyle(Paint.Style.FILL);
37	    paint.setColor(layerModel.getSolidColor());
38	  }
39	
40	  @Override public void drawLayer(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply) {
41	    int backgroundAlpha = Color.alpha(layerModel.getSolidColor());
42	    if (backgroundAlpha == 0) {
43	      return;
44	    }
45	
46	    Integer color = colorAnimation == null ? null : colorAnimation.getValue();
47	    if (color != null) {
48	      paint.setColor(color);
49	    } else {
50	      paint.setColor(layerModel.getSolidColor());
51	    }
52	
53	    int opacity = transform.getOpacity() == null ? 100 : transform.getOpacity().getValue();
54	    int alpha = (int) (parentAlpha / 255f * (backgroundAlpha / 255f * opacity / 100f) * 255);
55	    paint.setAlpha(alpha);
56	    if (shadowToApply != null) {
57	      shadowToApply.applyTo(paint);
58	    } else {
59	      paint.clearShadowLayer();
60	    }
61	
62	    if (colorFilterAnimation != null) {
63	      paint.setColorFilter(colorFilterAnimation.getValue());
64	    }
65	    if (alpha > 0) {
66	      points[0] = 0;
67	      points[1] = 0;
68	      points[2] = layerModel.getSolidWidth();
69	      points[3] = 0;
70	      points[4] = layerModel.getSolidWidth();
71	      points[5] = layerModel.getSolidHeight();
72	      points[6] = 0;
73	      points[7] = layerModel.getSolidHeight();
74	
75	      // We can't map rect here because if there is rotation on the transform then we aren't
76	      // actually drawing a rect.
77	      parentMatrix.mapPoints(points);
78	      path.reset();
79	      path.moveTo(points[0], points[1]);
80	      path.lineTo(points[2], points[3]);
81	      path.lineTo(points[4], points[5]);
82	      path.lineTo(points[6], points[7]);
83	      path.lineTo(points[0], points[1]);
84	      path.close();
85	      canvas.drawPath(path, paint);
86	    }
87	  }
88	
89	  @Override public void getBounds(RectF outBounds, Matrix parentMatrix, boolean applyParents) {
90	    super.getBounds(outBounds, parentMatrix, applyParents);
91	    rect.set(0, 0, layerModel.getSolidWidth(), layerModel.getSolidHeight());
92	    boundsMatrix.mapRect(rect);
93	    outBounds.set(rect);
94	  }
95	
96	  @SuppressWarnings("unchecked")
97	  @Override
98	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
99	    super.addValueCallback(property, callback);
100	    if (property == LottieProperty.COLOR_FILTER) {
101	      if (callback == null) {
102	        colorFilterAnimation = null;
103	      } else {
104	        colorFilterAnimation =
105	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<ColorFilter>) callback);
106	      }
107	    } else if (property == LottieProperty.COLOR) {
108	      if (callback == null) {
109	        colorAnimation = null;
110	        paint.setColor(layerModel.getSolidColor());
111	      } else {
112	        colorAnimation = new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Integer>) callback);
113	      }
114	    }
115	  }
116	}
