2	
3	import android.graphics.Bitmap;
4	import android.graphics.Canvas;
5	import android.graphics.ColorFilter;
6	import android.graphics.Matrix;
7	import android.graphics.Paint;
8	import android.graphics.Rect;
9	import android.graphics.RectF;
10	
11	import androidx.annotation.NonNull;
12	import androidx.annotation.Nullable;
13	
14	import com.airbnb.lottie.LottieDrawable;
15	import com.airbnb.lottie.LottieImageAsset;
16	import com.airbnb.lottie.LottieProperty;
17	import com.airbnb.lottie.animation.LPaint;
18	import com.airbnb.lottie.animation.keyframe.BaseKeyframeAnimation;
19	import com.airbnb.lottie.animation.keyframe.DropShadowKeyframeAnimation;
20	import com.airbnb.lottie.animation.keyframe.ValueCallbackKeyframeAnimation;
21	import com.airbnb.lottie.utils.DropShadow;
22	import com.airbnb.lottie.utils.OffscreenLayer;
23	import com.airbnb.lottie.utils.Utils;
24	import com.airbnb.lottie.value.LottieValueCallback;
25	
26	public class ImageLayer extends BaseLayer {
27	
28	  private final Paint paint = new LPaint(Paint.ANTI_ALIAS_FLAG | Paint.FILTER_BITMAP_FLAG);
29	  private final Rect src = new Rect();
30	  private final Rect dst = new Rect();
31	  private final RectF layerBounds = new RectF();
32	  @Nullable private final LottieImageAsset lottieImageAsset;
33	  @Nullable private BaseKeyframeAnimation<ColorFilter, ColorFilter> colorFilterAnimation;
34	  @Nullable private BaseKeyframeAnimation<Bitmap, Bitmap> imageAnimation;
35	  @Nullable private DropShadowKeyframeAnimation dropShadowAnimation;
36	  @Nullable private OffscreenLayer offscreenLayer;
37	  @Nullable private OffscreenLayer.ComposeOp offscreenOp;
38	
39	  ImageLayer(LottieDrawable lottieDrawable, Layer layerModel) {
40	    super(lottieDrawable, layerModel);
41	    lottieImageAsset = lottieDrawable.getLottieImageAssetForId(layerModel.getRefId());
42	
43	    if (getDropShadowEffect() != null) {
44	      dropShadowAnimation = new DropShadowKeyframeAnimation(this, this, getDropShadowEffect());
45	    }
46	  }
47	
48	  @Override public void drawLayer(@NonNull Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow parentShadowToApply) {
49	    Bitmap bitmap = getBitmap();
50	    if (bitmap == null || bitmap.isRecycled() || lottieImageAsset == null) {
51	      return;
52	    }
53	    float density = Utils.dpScale();
54	
55	    paint.setAlpha(parentAlpha);
56	    if (colorFilterAnimation != null) {
57	      paint.setColorFilter(colorFilterAnimation.getValue());
58	    }
59	
60	    @Nullable DropShadow shadowToApply = dropShadowAnimation != null
61	        ? dropShadowAnimation.evaluate(parentMatrix, parentAlpha)
62	        : parentShadowToApply;
63	
64	    src.set(0, 0, bitmap.getWidth(), bitmap.getHeight());
65	    if (lottieDrawable.getMaintainOriginalImageBounds()) {
66	      dst.set(0, 0, (int) (lottieImageAsset.getWidth() * density), (int) (lottieImageAsset.getHeight() * density));
67	    } else {
68	      dst.set(0, 0, (int) (bitmap.getWidth() * density), (int) (bitmap.getHeight() * density));
69	    }
70	
71	    // Render off-screen if we have a drop shadow, because:
72	    // - Android does not apply drop-shadows to bitmaps properly in HW accelerated contexts (blur is ignored)
73	    // - On some newer phones (empirically verified), no shadow is rendered at all even in software contexts.
74	    boolean renderOffScreen = shadowToApply != null;
75	    Canvas targetCanvas = canvas;
76	    if (renderOffScreen) {
77	      if (offscreenLayer == null) offscreenLayer = new OffscreenLayer();
78	      if (offscreenOp == null) offscreenOp = new OffscreenLayer.ComposeOp();
79	      offscreenOp.reset();
80	      // We don't use offscreenOp for compositing here, so we still need to account for its alpha
81	      // when drawing the shadow.
82	      shadowToApply.applyWithAlpha(parentAlpha, offscreenOp);
83	
84	
85	      // We don't use getBounds() as it expects the parent-to-world matrix, and what we have in parentMatrix is in
86	      // fact us-to-world (parent-to-world * us-to-parent)
87	      layerBounds.set(dst.left, dst.top, dst.right, dst.bottom);
88	      parentMatrix.mapRect(layerBounds);
89	      targetCanvas = offscreenLayer.start(canvas, layerBounds, offscreenOp);
90	    }
91	
92	    targetCanvas.save();
93	    targetCanvas.concat(parentMatrix);
94	    targetCanvas.drawBitmap(bitmap, src, dst, paint);
95	
96	    if (renderOffScreen) {
97	      offscreenLayer.finish();
98	      if (offscreenLayer.finishDecrementsCanvasSaveCount()) {
99	        return; // Don't need a restore() call since it's handled by OffscreenLayer
100	      }
101	    }
102	
103	    targetCanvas.restore();
104	  }
105	
106	  @Override public void getBounds(RectF outBounds, Matrix parentMatrix, boolean applyParents) {
107	    super.getBounds(outBounds, parentMatrix, applyParents);
108	    if (lottieImageAsset != null) {
109	      float scale = Utils.dpScale();
110	      if (lottieDrawable.getMaintainOriginalImageBounds()) {
111	        outBounds.set(0, 0, lottieImageAsset.getWidth() * scale, lottieImageAsset.getHeight() * scale);
112	      } else {
113	        Bitmap bitmap = getBitmap();
114	        if (bitmap != null) {
115	          outBounds.set(0, 0, bitmap.getWidth() * scale, bitmap.getHeight() * scale);
116	        } else {
117	          // If the bitmap is null, fall back to using the width and height of the LottieImageAsset
118	          outBounds.set(0, 0, lottieImageAsset.getWidth() * scale, lottieImageAsset.getHeight() * scale);
119	        }
120	      }
121	      boundsMatrix.mapRect(outBounds);
122	    }
123	  }
124	
125	  @Nullable
126	  private Bitmap getBitmap() {
127	    if (imageAnimation != null) {
128	      Bitmap callbackBitmap = imageAnimation.getValue();
129	      if (callbackBitmap != null) {
130	        return callbackBitmap;
131	      }
132	    }
133	    String refId = layerModel.getRefId();
134	    Bitmap bitmapFromDrawable = lottieDrawable.getBitmapForId(refId);
135	    if (bitmapFromDrawable != null) {
136	      return bitmapFromDrawable;
137	    }
138	    LottieImageAsset asset = this.lottieImageAsset;
139	    if (asset != null) {
140	      return asset.getBitmap();
141	    }
142	    return null;
143	  }
144	
145	  @SuppressWarnings("SingleStatementInBlock")
146	  @Override
147	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
148	    super.addValueCallback(property, callback);
149	    if (property == LottieProperty.COLOR_FILTER) {
150	      if (callback == null) {
151	        colorFilterAnimation = null;
152	      } else {
153	        //noinspection unchecked
154	        colorFilterAnimation =
155	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<ColorFilter>) callback);
156	      }
157	    } else if (property == LottieProperty.IMAGE) {
158	      if (callback == null) {
159	        imageAnimation = null;
160	      } else {
161	        //noinspection unchecked
162	        imageAnimation =
163	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Bitmap>) callback);
164	      }
165	    } else if (property == LottieProperty.DROP_SHADOW_COLOR && dropShadowAnimation != null) {
166	        dropShadowAnimation.setColorCallback((LottieValueCallback<Integer>) callback);
167	    } else if (property == LottieProperty.DROP_SHADOW_OPACITY && dropShadowAnimation != null) {
168	      dropShadowAnimation.setOpacityCallback((LottieValueCallback<Float>) callback);
169	    } else if (property == LottieProperty.DROP_SHADOW_DIRECTION && dropShadowAnimation != null) {
170	      dropShadowAnimation.setDirectionCallback((LottieValueCallback<Float>) callback);
171	    } else if (property == LottieProperty.DROP_SHADOW_DISTANCE && dropShadowAnimation != null) {
172	      dropShadowAnimation.setDistanceCallback((LottieValueCallback<Float>) callback);
173	    } else if (property == LottieProperty.DROP_SHADOW_RADIUS && dropShadowAnimation != null) {
174	      dropShadowAnimation.setRadiusCallback((LottieValueCallback<Float>) callback);
175	    }
176	  }
177	}
