2	
3	import androidx.annotation.Nullable;
4	import com.airbnb.lottie.LottieComposition;
5	import com.airbnb.lottie.model.animatable.AnimatableColorValue;
6	import com.airbnb.lottie.model.animatable.AnimatableFloatValue;
7	import com.airbnb.lottie.model.animatable.AnimatableIntegerValue;
8	import com.airbnb.lottie.model.animatable.AnimatableTextProperties;
9	import com.airbnb.lottie.model.animatable.AnimatableTextRangeSelector;
10	import com.airbnb.lottie.model.animatable.AnimatableTextStyle;
11	import com.airbnb.lottie.model.content.LBlendMode;
12	import com.airbnb.lottie.model.content.TextRangeUnits;
13	import com.airbnb.lottie.parser.moshi.JsonReader;
14	import com.airbnb.lottie.value.Keyframe;
15	
16	import java.io.IOException;
17	import java.util.Collections;
18	
19	public class AnimatableTextPropertiesParser {
20	
21	  private static final JsonReader.Options PROPERTIES_NAMES = JsonReader.Options.of("s", "a");
22	
23	  private static final JsonReader.Options ANIMATABLE_RANGE_PROPERTIES_NAMES = JsonReader.Options.of(
24	      "s", // start
25	      "e", // end
26	      "o", // offset
27	      "r" // text range units (percent or index)
28	  );
29	  private static final JsonReader.Options ANIMATABLE_PROPERTIES_NAMES = JsonReader.Options.of(
30	      "fc",
31	      "sc",
32	      "sw",
33	      "t",
34	      "o" // opacity
35	  );
36	
37	  private AnimatableTextPropertiesParser() {
38	  }
39	
40	  public static AnimatableTextProperties parse(
41	      JsonReader reader, LottieComposition composition) throws IOException {
42	    @Nullable AnimatableTextStyle textStyle = null;
43	    @Nullable AnimatableTextRangeSelector rangeSelector = null;
44	
45	    reader.beginObject();
46	    while (reader.hasNext()) {
47	      switch (reader.selectName(PROPERTIES_NAMES)) {
48	        case 0: // Range selector
49	          rangeSelector = parseAnimatableTextRangeSelector(reader, composition);
50	          break;
51	        case 1: // Text style for this range
52	          textStyle = parseAnimatableTextStyle(reader, composition);
53	          break;
54	        default:
55	          reader.skipName();
56	          reader.skipValue();
57	      }
58	    }
59	    reader.endObject();
60	
61	    return new AnimatableTextProperties(textStyle, rangeSelector);
62	  }
63	
64	  private static AnimatableTextRangeSelector parseAnimatableTextRangeSelector(JsonReader reader, LottieComposition composition) throws IOException {
65	    // TODO These may need to be floats in the future if we want to support percentage based ranges.
66	    AnimatableIntegerValue start = null;
67	    AnimatableIntegerValue end = null;
68	    AnimatableIntegerValue offset = null;
69	    TextRangeUnits units = null;
70	
71	    reader.beginObject();
72	    while (reader.hasNext()) {
73	      switch (reader.selectName(ANIMATABLE_RANGE_PROPERTIES_NAMES)) {
74	        case 0: // start
75	          start = AnimatableValueParser.parseInteger(reader, composition);
76	          break;
77	        case 1: // end
78	          end = AnimatableValueParser.parseInteger(reader, composition);
79	          break;
80	        case 2: // offset
81	          offset = AnimatableValueParser.parseInteger(reader, composition);
82	          break;
83	        case 3: // text range units (percent or index)
84	          int textRangeUnits = reader.nextInt();
85	          if (textRangeUnits != 1 && textRangeUnits != 2) {
86	            composition.addWarning("Unsupported text range units: " + textRangeUnits);
87	            units = TextRangeUnits.INDEX;
88	            break;
89	          }
90	          units = textRangeUnits == 1 ? TextRangeUnits.PERCENT : TextRangeUnits.INDEX;
91	          break;
92	        default:
93	          reader.skipName();
94	          reader.skipValue();
95	      }
96	    }
97	    reader.endObject();
98	
99	    // If no start value is provided, default to a non-animated value of 0 to match After Effects/Bodymovin.
100	    if (start == null && end != null) {
101	      start = new AnimatableIntegerValue(Collections.singletonList(new Keyframe<>(0)));
102	    }
103	
104	    return new AnimatableTextRangeSelector(start, end, offset, units);
105	  }
106	
107	  private static AnimatableTextStyle parseAnimatableTextStyle(
108	      JsonReader reader, LottieComposition composition) throws IOException {
109	    AnimatableColorValue color = null;
110	    AnimatableColorValue stroke = null;
111	    AnimatableFloatValue strokeWidth = null;
112	    AnimatableFloatValue tracking = null;
113	    AnimatableIntegerValue opacity = null;
114	
115	    reader.beginObject();
116	    while (reader.hasNext()) {
117	      switch (reader.selectName(ANIMATABLE_PROPERTIES_NAMES)) {
118	        case 0:
119	          color = AnimatableValueParser.parseColor(reader, composition);
120	          break;
121	        case 1:
122	          stroke = AnimatableValueParser.parseColor(reader, composition);
123	          break;
124	        case 2:
125	          strokeWidth = AnimatableValueParser.parseFloat(reader, composition);
126	          break;
127	        case 3:
128	          tracking = AnimatableValueParser.parseFloat(reader, composition);
129	          break;
130	        case 4: // opacity
131	          opacity = AnimatableValueParser.parseInteger(reader, composition);
132	          break;
133	        default:
134	          reader.skipName();
135	          reader.skipValue();
136	      }
137	    }
138	    reader.endObject();
139	
140	    return new AnimatableTextStyle(color, stroke, strokeWidth, tracking, opacity);
141	  }
142	}
