1	package com.airbnb.lottie.parser;
2	
3	import android.graphics.Path;
4	
5	import com.airbnb.lottie.LottieComposition;
6	import com.airbnb.lottie.model.animatable.AnimatableGradientColorValue;
7	import com.airbnb.lottie.model.animatable.AnimatableIntegerValue;
8	import com.airbnb.lottie.model.animatable.AnimatablePointValue;
9	import com.airbnb.lottie.model.content.GradientFill;
10	import com.airbnb.lottie.model.content.GradientType;
11	import com.airbnb.lottie.parser.moshi.JsonReader;
12	import com.airbnb.lottie.value.Keyframe;
13	
14	import java.io.IOException;
15	import java.util.Collections;
16	
17	class GradientFillParser {
18	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
19	      "nm",
20	      "g",
21	      "o",
22	      "t",
23	      "s",
24	      "e",
25	      "r",
26	      "hd"
27	  );
28	  private static final JsonReader.Options GRADIENT_NAMES = JsonReader.Options.of(
29	      "p",
30	      "k"
31	  );
32	
33	  private GradientFillParser() {
34	  }
35	
36	  static GradientFill parse(
37	      JsonReader reader, LottieComposition composition) throws IOException {
38	    String name = null;
39	    AnimatableGradientColorValue color = null;
40	    AnimatableIntegerValue opacity = null;
41	    GradientType gradientType = null;
42	    AnimatablePointValue startPoint = null;
43	    AnimatablePointValue endPoint = null;
44	    Path.FillType fillType = Path.FillType.WINDING;
45	    boolean hidden = false;
46	
47	    while (reader.hasNext()) {
48	      switch (reader.selectName(NAMES)) {
49	        case 0:
50	          name = reader.nextString();
51	          break;
52	        case 1:
53	          int points = -1;
54	          reader.beginObject();
55	          while (reader.hasNext()) {
56	            switch (reader.selectName(GRADIENT_NAMES)) {
57	              case 0:
58	                points = reader.nextInt();
59	                break;
60	              case 1:
61	                color = AnimatableValueParser.parseGradientColor(reader, composition, points);
62	                break;
63	              default:
64	                reader.skipName();
65	                reader.skipValue();
66	            }
67	          }
68	          reader.endObject();
69	          break;
70	        case 2:
71	          opacity = AnimatableValueParser.parseInteger(reader, composition);
72	          break;
73	        case 3:
74	          gradientType = reader.nextInt() == 1 ? GradientType.LINEAR : GradientType.RADIAL;
75	          break;
76	        case 4:
77	          startPoint = AnimatableValueParser.parsePoint(reader, composition);
78	          break;
79	        case 5:
80	          endPoint = AnimatableValueParser.parsePoint(reader, composition);
81	          break;
82	        case 6:
83	          fillType = reader.nextInt() == 1 ? Path.FillType.WINDING : Path.FillType.EVEN_ODD;
84	          break;
85	        case 7:
86	          hidden = reader.nextBoolean();
87	          break;
88	        default:
89	          reader.skipName();
90	          reader.skipValue();
91	      }
92	    }
93	
94	    // Telegram sometimes omits opacity.
95	    // https://github.com/airbnb/lottie-android/issues/1600
96	    opacity = opacity == null ? new AnimatableIntegerValue(Collections.singletonList(new Keyframe<>(100))) : opacity;
97	    return new GradientFill(
98	        name, gradientType, fillType, color, opacity, startPoint, endPoint, null, null, hidden);
99	  }
100	}
