1	package com.airbnb.lottie.parser;
2	
3	
4	import com.airbnb.lottie.LottieComposition;
5	import com.airbnb.lottie.model.animatable.AnimatableFloatValue;
6	import com.airbnb.lottie.model.animatable.AnimatableGradientColorValue;
7	import com.airbnb.lottie.model.animatable.AnimatableIntegerValue;
8	import com.airbnb.lottie.model.animatable.AnimatablePointValue;
9	import com.airbnb.lottie.model.content.GradientStroke;
10	import com.airbnb.lottie.model.content.GradientType;
11	import com.airbnb.lottie.model.content.ShapeStroke;
12	import com.airbnb.lottie.parser.moshi.JsonReader;
13	import com.airbnb.lottie.value.Keyframe;
14	
15	import java.io.IOException;
16	import java.util.ArrayList;
17	import java.util.Collections;
18	import java.util.List;
19	
20	class GradientStrokeParser {
21	
22	  private GradientStrokeParser() {
23	  }
24	
25	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
26	      "nm",
27	      "g",
28	      "o",
29	      "t",
30	      "s",
31	      "e",
32	      "w",
33	      "lc",
34	      "lj",
35	      "ml",
36	      "hd",
37	      "d"
38	  );
39	  private static final JsonReader.Options GRADIENT_NAMES = JsonReader.Options.of(
40	      "p",
41	      "k"
42	  );
43	  private static final JsonReader.Options DASH_PATTERN_NAMES = JsonReader.Options.of(
44	      "n",
45	      "v"
46	  );
47	
48	  static GradientStroke parse(
49	      JsonReader reader, LottieComposition composition) throws IOException {
50	    String name = null;
51	    AnimatableGradientColorValue color = null;
52	    AnimatableIntegerValue opacity = null;
53	    GradientType gradientType = null;
54	    AnimatablePointValue startPoint = null;
55	    AnimatablePointValue endPoint = null;
56	    AnimatableFloatValue width = null;
57	    ShapeStroke.LineCapType capType = null;
58	    ShapeStroke.LineJoinType joinType = null;
59	    AnimatableFloatValue offset = null;
60	    float miterLimit = 0f;
61	    boolean hidden = false;
62	
63	
64	    List<AnimatableFloatValue> lineDashPattern = new ArrayList<>();
65	
66	    while (reader.hasNext()) {
67	      switch (reader.selectName(NAMES)) {
68	        case 0:
69	          name = reader.nextString();
70	          break;
71	        case 1:
72	          int points = -1;
73	          reader.beginObject();
74	          while (reader.hasNext()) {
75	            switch (reader.selectName(GRADIENT_NAMES)) {
76	              case 0:
77	                points = reader.nextInt();
78	                break;
79	              case 1:
80	                color = AnimatableValueParser.parseGradientColor(reader, composition, points);
81	                break;
82	              default:
83	                reader.skipName();
84	                reader.skipValue();
85	            }
86	          }
87	          reader.endObject();
88	          break;
89	        case 2:
90	          opacity = AnimatableValueParser.parseInteger(reader, composition);
91	          break;
92	        case 3:
93	          gradientType = reader.nextInt() == 1 ? GradientType.LINEAR : GradientType.RADIAL;
94	          break;
95	        case 4:
96	          startPoint = AnimatableValueParser.parsePoint(reader, composition);
97	          break;
98	        case 5:
99	          endPoint = AnimatableValueParser.parsePoint(reader, composition);
100	          break;
101	        case 6:
102	          width = AnimatableValueParser.parseFloat(reader, composition);
103	          break;
104	        case 7:
105	          capType = ShapeStroke.LineCapType.values()[reader.nextInt() - 1];
106	          break;
107	        case 8:
108	          joinType = ShapeStroke.LineJoinType.values()[reader.nextInt() - 1];
109	          break;
110	        case 9:
111	          miterLimit = (float) reader.nextDouble();
112	          break;
113	        case 10:
114	          hidden = reader.nextBoolean();
115	          break;
116	        case 11:
117	          reader.beginArray();
118	          while (reader.hasNext()) {
119	            String n = null;
120	            AnimatableFloatValue val = null;
121	            reader.beginObject();
122	            while (reader.hasNext()) {
123	              switch (reader.selectName(DASH_PATTERN_NAMES)) {
124	                case 0:
125	                  n = reader.nextString();
126	                  break;
127	                case 1:
128	                  val = AnimatableValueParser.parseFloat(reader, composition);
129	                  break;
130	                default:
131	                  reader.skipName();
132	                  reader.skipValue();
133	              }
134	            }
135	            reader.endObject();
136	
137	            if (n.equals("o")) {
138	              offset = val;
139	            } else if (n.equals("d") || n.equals("g")) {
140	              composition.setHasDashPattern(true);
141	              lineDashPattern.add(val);
142	            }
143	          }
144	          reader.endArray();
145	          if (lineDashPattern.size() == 1) {
146	            // If there is only 1 value then it is assumed to be equal parts on and off.
147	            lineDashPattern.add(lineDashPattern.get(0));
148	          }
149	          break;
150	        default:
151	          reader.skipName();
152	          reader.skipValue();
153	      }
154	    }
155	
156	    // Telegram sometimes omits opacity.
157	    // https://github.com/airbnb/lottie-android/issues/1600
158	    opacity = opacity == null ? new AnimatableIntegerValue(Collections.singletonList(new Keyframe<>(100))) : opacity;
159	    return new GradientStroke(
160	        name, gradientType, color, opacity, startPoint, endPoint, width, capType, joinType,
161	        miterLimit, lineDashPattern, offset, hidden);
162	  }
163	}
