7	import com.airbnb.lottie.LottieDrawable;
8	import com.airbnb.lottie.LottieProperty;
9	import com.airbnb.lottie.animation.keyframe.BaseKeyframeAnimation;
10	import com.airbnb.lottie.animation.keyframe.ShapeKeyframeAnimation;
11	import com.airbnb.lottie.model.KeyPath;
12	import com.airbnb.lottie.model.content.ShapePath;
13	import com.airbnb.lottie.model.content.ShapeTrimPath;
14	import com.airbnb.lottie.model.layer.BaseLayer;
15	import com.airbnb.lottie.utils.MiscUtils;
16	import com.airbnb.lottie.value.LottieValueCallback;
17	
18	import java.util.ArrayList;
19	import java.util.List;
20	
21	public class ShapeContent implements PathContent, BaseKeyframeAnimation.AnimationListener, KeyPathElementContent {
22	  private final Path path = new Path();
23	
24	  private final String name;
25	  private final boolean hidden;
26	  private final LottieDrawable lottieDrawable;
27	  private final ShapeKeyframeAnimation shapeAnimation;
28	  @Nullable private List<ShapeModifierContent> shapeModifierContents;
29	
30	  private boolean isPathValid;
31	  private final CompoundTrimPathContent trimPaths = new CompoundTrimPathContent();
32	
33	  public ShapeContent(LottieDrawable lottieDrawable, BaseLayer layer, ShapePath shape) {
34	    name = shape.getName();
35	    hidden = shape.isHidden();
36	    this.lottieDrawable = lottieDrawable;
37	    shapeAnimation = shape.getShapePath().createAnimation();
38	    layer.addAnimation(shapeAnimation);
39	    shapeAnimation.addUpdateListener(this);
40	  }
41	
42	  @Override public void onValueChanged() {
43	    invalidate();
44	  }
45	
46	  private void invalidate() {
47	    isPathValid = false;
48	    lottieDrawable.invalidateSelf();
49	  }
50	
51	  @Override public void setContents(List<Content> contentsBefore, List<Content> contentsAfter) {
52	    @Nullable List<ShapeModifierContent> shapeModifierContents = null;
53	    for (Content content : contentsBefore) {
54	      if (content instanceof TrimPathContent &&
55	          ((TrimPathContent) content).getType() == ShapeTrimPath.Type.SIMULTANEOUSLY) {
56	        // Trim path individually will be handled by the stroke where paths are combined.
57	        TrimPathContent trimPath = (TrimPathContent) content;
58	        trimPaths.addTrimPath(trimPath);
59	        trimPath.addListener(this);
60	      } else if (content instanceof ShapeModifierContent) {
61	        if (shapeModifierContents == null) {
62	          shapeModifierContents = new ArrayList<>();
63	        }
64	        ((ShapeModifierContent) content).addUpdateListener(this);
65	        shapeModifierContents.add((ShapeModifierContent) content);
66	      }
67	    }
68	    shapeAnimation.setShapeModifiers(shapeModifierContents);
69	  }
70	
71	  @Override public Path getPath() {
72	    if (isPathValid && !shapeAnimation.hasValueCallback()) {
73	      return path;
74	    }
75	
76	    path.reset();
77	
78	    if (hidden) {
79	      isPathValid = true;
80	      return path;
81	    }
82	
83	    Path shapeAnimationPath = shapeAnimation.getValue();
84	    if (shapeAnimationPath == null) {
85	      // It is unclear why this ever returns null but it seems to in rare cases.
86	      // https://github.com/airbnb/lottie-android/issues/1632
87	      return path;
88	    }
89	    path.set(shapeAnimationPath);
90	    path.setFillType(Path.FillType.EVEN_ODD);
91	
92	    trimPaths.apply(path);
93	
94	    isPathValid = true;
95	    return path;
96	  }
97	
98	  @Override public String getName() {
99	    return name;
100	  }
101	
102	  @Override public void resolveKeyPath(
103	      KeyPath keyPath, int depth, List<KeyPath> accumulator, KeyPath currentPartialKeyPath) {
104	    MiscUtils.resolveKeyPath(keyPath, depth, accumulator, currentPartialKeyPath, this);
105	  }
