107	  @SuppressWarnings("unchecked")
108	  @Override
109	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
110	    if (property == LottieProperty.PATH) {
111	      shapeAnimation.setValueCallback((LottieValueCallback<Path>) callback);
112	    }
113	  }
