21	public class SolidLayer extends BaseLayer {
22	
23	  private final RectF rect = new RectF();
24	  private final Paint paint = new LPaint();
25	  private final float[] points = new float[8];
26	  private final Path path = new Path();
27	  private final Layer layerModel;
28	  @Nullable private BaseKeyframeAnimation<ColorFilter, ColorFilter> colorFilterAnimation;
29	  @Nullable private BaseKeyframeAnimation<Integer, Integer> colorAnimation;
30	
31	  SolidLayer(LottieDrawable lottieDrawable, Layer layerModel) {
32	    super(lottieDrawable, layerModel);
33	    this.layerModel = layerModel;
34	
35	    paint.setAlpha(0);
36	    paint.setStyle(Paint.Style.FILL);
37	    paint.setColor(layerModel.getSolidColor());
38	  }
39	
40	  @Override public void drawLayer(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply) {
41	    int backgroundAlpha = Color.alpha(layerModel.getSolidColor());
42	    if (backgroundAlpha == 0) {
43	      return;
44	    }
45	
46	    Integer color = colorAnimation == null ? null : colorAnimation.getValue();
47	    if (color != null) {
48	      paint.setColor(color);
49	    } else {
50	      paint.setColor(layerModel.getSolidColor());
51	    }
52	
53	    int opacity = transform.getOpacity() == null ? 100 : transform.getOpacity().getValue();
54	    int alpha = (int) (parentAlpha / 255f * (backgroundAlpha / 255f * opacity / 100f) * 255);
55	    paint.setAlpha(alpha);
56	    if (shadowToApply != null) {
57	      shadowToApply.applyTo(paint);
58	    } else {
59	      paint.clearShadowLayer();
60	    }
61	
62	    if (colorFilterAnimation != null) {
63	      paint.setColorFilter(colorFilterAnimation.getValue());
64	    }
65	    if (alpha > 0) {
66	      points[0] = 0;
67	      points[1] = 0;
68	      points[2] = layerModel.getSolidWidth();
69	      points[3] = 0;
70	      points[4] = layerModel.getSolidWidth();
71	      points[5] = layerModel.getSolidHeight();
